FILES = {'buster/living/mission_events.py': 'from __future__ import annotations\n\nclass MissionEventType:\n    PLANNER_CREATED_MISSION = "planner.created_mission"\n    REPOSITORY_INDEXED = "repository.indexed"\n    BUILDER_GENERATED_CODE = "builder.generated_code"\n    TESTER_FOUND_FAILURE = "tester.found_failure"\n    TESTER_PASSED = "tester.passed"\n    FIXER_REPAIRED_ISSUE = "fixer.repaired_issue"\n    REVIEWER_REVIEWED = "reviewer.reviewed"\n    VERIFIER_APPROVED_BUILD = "verifier.approved_build"\n    LEARNING_RECORDED_PATTERN = "learning.recorded_pattern"\n    EXPERIENCE_UPDATED_SKILL = "experience.updated_skill"\n    PLUGIN_LOADED = "plugin.loaded"\n    MISSION_COMPLETED = "mission.completed"\n    MISSION_FAILED = "mission.failed"\n\nEVENT_LABELS = {\n    MissionEventType.PLANNER_CREATED_MISSION: ("Planner", "created mission"),\n    MissionEventType.REPOSITORY_INDEXED: ("Repository", "indexed project"),\n    MissionEventType.BUILDER_GENERATED_CODE: ("Builder", "generated code"),\n    MissionEventType.TESTER_FOUND_FAILURE: ("Tester", "found failure"),\n    MissionEventType.TESTER_PASSED: ("Tester", "tests passed"),\n    MissionEventType.FIXER_REPAIRED_ISSUE: ("Fixer", "repaired issue"),\n    MissionEventType.REVIEWER_REVIEWED: ("Reviewer", "reviewed output"),\n    MissionEventType.VERIFIER_APPROVED_BUILD: ("Verifier", "approved build"),\n    MissionEventType.LEARNING_RECORDED_PATTERN: ("Learning Engine", "recorded new pattern"),\n    MissionEventType.EXPERIENCE_UPDATED_SKILL: ("Experience", "updated skill"),\n    MissionEventType.PLUGIN_LOADED: ("Plugin OS", "loaded plugin"),\n    MissionEventType.MISSION_COMPLETED: ("Mission", "completed"),\n    MissionEventType.MISSION_FAILED: ("Mission", "failed"),\n}\n\ndef source_for_event(event_type: str) -> str:\n    return EVENT_LABELS.get(event_type, ("System", event_type))[0]\n\ndef default_message_for_event(event_type: str) -> str:\n    return EVENT_LABELS.get(event_type, ("System", event_type))[1]\n', 'buster/living/live_timeline.py': 'from __future__ import annotations\n\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any, Dict, List, Optional\nimport json\n\nfrom .mission_events import default_message_for_event, source_for_event\n\ndef utc_now() -> str:\n    return datetime.now(timezone.utc).isoformat(timespec="seconds")\n\nclass LiveMissionTimeline:\n    """Timeline used by Mission Control to show Buster thinking live."""\n    def __init__(self, path: str | Path = "data/mission_timeline_live.json", limit: int = 1000):\n        self.path = Path(path)\n        self.limit = limit\n        self.path.parent.mkdir(parents=True, exist_ok=True)\n        if not self.path.exists():\n            self.path.write_text("[]", encoding="utf-8")\n\n    def _read(self) -> List[Dict[str, Any]]:\n        try:\n            data = json.loads(self.path.read_text(encoding="utf-8"))\n            return data if isinstance(data, list) else []\n        except Exception:\n            return []\n\n    def _write(self, events: List[Dict[str, Any]]) -> None:\n        self.path.write_text(json.dumps(events[-self.limit:], indent=2), encoding="utf-8")\n\n    def record(self, event_type: str, message: Optional[str] = None, *, source: Optional[str] = None, mission_id: str = "default", level: str = "info", confidence: Optional[float] = None, risk: Optional[str] = None, agent: Optional[str] = None, details: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:\n        event = {\n            "timestamp": utc_now(),\n            "mission_id": mission_id,\n            "event_type": event_type,\n            "source": source or agent or source_for_event(event_type),\n            "agent": agent or source or source_for_event(event_type),\n            "message": message or default_message_for_event(event_type),\n            "level": level,\n            "confidence": confidence,\n            "risk": risk or "unknown",\n            "details": details or {},\n        }\n        events = self._read()\n        events.append(event)\n        self._write(events)\n        return event\n\n    def recent(self, count: int = 20, mission_id: Optional[str] = None) -> List[Dict[str, Any]]:\n        events = self._read()\n        if mission_id:\n            events = [e for e in events if e.get("mission_id") == mission_id]\n        return events[-count:]\n\n    def clear(self) -> None:\n        self._write([])\n\n    def line_for(self, event: Dict[str, Any]) -> str:\n        timestamp = str(event.get("timestamp", ""))\n        time_part = timestamp.split("T")[-1][:5] if "T" in timestamp else timestamp[:5]\n        source = event.get("source") or event.get("agent") or "System"\n        message = event.get("message") or "updated"\n        confidence = event.get("confidence")\n        risk = event.get("risk")\n        suffix = ""\n        if confidence is not None:\n            try:\n                suffix += f" | confidence {float(confidence) * 100:.0f}%"\n            except Exception:\n                suffix += f" | confidence {confidence}"\n        if risk and risk != "unknown":\n            suffix += f" | risk {risk}"\n        return f"{time_part}  {source} {message}{suffix}"\n\n    def lines(self, count: int = 20, mission_id: Optional[str] = None) -> List[str]:\n        return [self.line_for(e) for e in self.recent(count=count, mission_id=mission_id)]\n', 'buster/living/event_bridge.py': 'from __future__ import annotations\n\nfrom typing import Any, Dict\nfrom .live_timeline import LiveMissionTimeline\nfrom .mission_events import MissionEventType\n\nclass MissionTimelineEventBridge:\n    """Connects Buster\'s Event Bus to the Living OS mission timeline."""\n    def __init__(self, timeline: LiveMissionTimeline | None = None):\n        self.timeline = timeline or LiveMissionTimeline()\n\n    def handle(self, event: Dict[str, Any]) -> Dict[str, Any]:\n        event_type = str(event.get("type") or event.get("event_type") or event.get("name") or "system.event")\n        payload = event.get("payload") if isinstance(event.get("payload"), dict) else event\n        mission_id = str(payload.get("mission_id", event.get("mission_id", "default")))\n        message = payload.get("message") or payload.get("summary") or payload.get("description")\n        source = payload.get("source") or event.get("source")\n        agent = payload.get("agent") or event.get("agent")\n        level = str(payload.get("level", event.get("level", "info")))\n        confidence = payload.get("confidence", event.get("confidence"))\n        risk = payload.get("risk", event.get("risk", "unknown"))\n        details = payload.get("details") if isinstance(payload.get("details"), dict) else {}\n        if not details:\n            details = {k: v for k, v in payload.items() if k not in {"message", "summary", "description", "source", "agent", "level", "confidence", "risk", "mission_id"}}\n        return self.timeline.record(event_type, message, source=source, mission_id=mission_id, level=level, confidence=confidence, risk=risk, agent=agent, details=details)\n\n    def subscribe_to(self, bus: Any) -> bool:\n        for method_name in ("subscribe", "on", "add_listener"):\n            method = getattr(bus, method_name, None)\n            if callable(method):\n                try:\n                    method(self.handle)\n                    return True\n                except TypeError:\n                    try:\n                        method("*", self.handle)\n                        return True\n                    except TypeError:\n                        continue\n        return False\n\n    def demo_sequence(self, mission: str = "Example build", project: str = "example_project") -> None:\n        self.handle({"type": MissionEventType.PLANNER_CREATED_MISSION, "payload": {"message": f"created mission: {mission}", "confidence": 0.91, "risk": "low"}})\n        self.handle({"type": MissionEventType.REPOSITORY_INDEXED, "payload": {"message": f"indexed project: {project}"}})\n        self.handle({"type": MissionEventType.BUILDER_GENERATED_CODE, "payload": {"message": "generated code: main.py"}})\n        self.handle({"type": MissionEventType.TESTER_FOUND_FAILURE, "payload": {"message": "found 1 failure", "level": "warning", "risk": "medium"}})\n        self.handle({"type": MissionEventType.FIXER_REPAIRED_ISSUE, "payload": {"message": "repaired import error", "confidence": 0.82, "risk": "low"}})\n        self.handle({"type": MissionEventType.VERIFIER_APPROVED_BUILD, "payload": {"message": "approved build", "confidence": 0.94, "risk": "low"}})\n        self.handle({"type": MissionEventType.LEARNING_RECORDED_PATTERN, "payload": {"message": "recorded new pattern: safe import guard"}})\n        self.handle({"type": MissionEventType.EXPERIENCE_UPDATED_SKILL, "payload": {"message": "updated Python skill (+0.2%)"}})\n', 'buster/workspace/live_mission_timeline.py': 'from __future__ import annotations\nfrom typing import Any, Dict\nfrom buster.living.live_timeline import LiveMissionTimeline\nfrom buster.living.event_bridge import MissionTimelineEventBridge\n\nclass LiveMissionTimelineView:\n    """Mission Control view model for the live timeline."""\n    def __init__(self):\n        self.timeline = LiveMissionTimeline()\n        self.bridge = MissionTimelineEventBridge(self.timeline)\n    def record_event(self, event: Dict[str, Any]) -> Dict[str, Any]:\n        return self.bridge.handle(event)\n    def get_view_model(self, count: int = 25) -> Dict[str, Any]:\n        events = self.timeline.recent(count)\n        return {"title": "Live Mission Timeline", "count": len(events), "events": events, "lines": [self.timeline.line_for(e) for e in events]}\n', 'buster/ui/widgets/live_mission_timeline_widget.py': 'from __future__ import annotations\nfrom typing import Any, Dict\nfrom buster.workspace.live_mission_timeline import LiveMissionTimelineView\n\nclass LiveMissionTimelineWidgetModel:\n    """UI-safe widget model for the Jarvis-style live timeline."""\n    def __init__(self):\n        self.view = LiveMissionTimelineView()\n    def get_view_model(self) -> Dict[str, Any]:\n        model = self.view.get_view_model(20)\n        model["empty_message"] = "No mission activity yet. Start a mission to watch Buster think."\n        return model\n', 'buster/brain/planner/timeline_planner_bridge.py': 'from __future__ import annotations\nfrom typing import Any, Dict\nfrom buster.living.event_bridge import MissionTimelineEventBridge\nfrom buster.living.mission_events import MissionEventType\n\nclass TimelinePlannerBridge:\n    """Publishes planner decisions directly to the live mission timeline."""\n    def __init__(self):\n        self.bridge = MissionTimelineEventBridge()\n    def mission_created(self, mission: str, confidence: float = 0.0, risk: str = "unknown", reason: str = "") -> Dict[str, Any]:\n        return self.bridge.handle({"type": MissionEventType.PLANNER_CREATED_MISSION, "payload": {"message": f"created mission: {mission}", "mission": mission, "confidence": confidence, "risk": risk, "details": {"reason": reason}}})\n    def agent_step(self, agent: str, message: str, confidence: float | None = None, risk: str = "unknown") -> Dict[str, Any]:\n        return self.bridge.handle({"type": f"agent.{agent.lower()}.step", "payload": {"agent": agent, "source": agent, "message": message, "confidence": confidence, "risk": risk}})\n', 'buster/living/__init__.py': '"""Living OS layer for Buster."""\ntry:\n    from .state import LivingState, LivingMood\n    from .engine import LivingOSEngine\n    from .timeline import ActivityTimeline, TimelineEvent\n    from .notifications import DecisionNotification\n    from .face_controller import FaceController\n    from .voice_vision_bridge import VoiceVisionBridge\n    from .live_timeline import LiveMissionTimeline\n    from .event_bridge import MissionTimelineEventBridge\n    from .mission_events import MissionEventType\nexcept Exception:\n    pass\n\n__all__ = ["LivingState", "LivingMood", "LivingOSEngine", "ActivityTimeline", "TimelineEvent", "DecisionNotification", "FaceController", "VoiceVisionBridge", "LiveMissionTimeline", "MissionTimelineEventBridge", "MissionEventType"]\n'}
FILES["test_v4_2_live_mission_timeline.py"] = '#!/usr/bin/env python3\nfrom __future__ import annotations\nfrom pathlib import Path\nimport json\n\ndef assert_file(path: str) -> None:\n    if not Path(path).exists():\n        raise AssertionError(f"Missing file: {path}")\n\ndef main() -> None:\n    required = [\n        "buster/living/mission_events.py",\n        "buster/living/live_timeline.py",\n        "buster/living/event_bridge.py",\n        "buster/workspace/live_mission_timeline.py",\n        "buster/ui/widgets/live_mission_timeline_widget.py",\n        "buster/brain/planner/timeline_planner_bridge.py",\n        "data/live_mission_timeline_state.json",\n        "data/mission_timeline_live.json",\n    ]\n    for item in required:\n        assert_file(item)\n    from buster.living.live_timeline import LiveMissionTimeline\n    from buster.living.event_bridge import MissionTimelineEventBridge\n    from buster.living.mission_events import MissionEventType\n    from buster.workspace.live_mission_timeline import LiveMissionTimelineView\n    from buster.ui.widgets.live_mission_timeline_widget import LiveMissionTimelineWidgetModel\n    from buster.brain.planner.timeline_planner_bridge import TimelinePlannerBridge\n    timeline = LiveMissionTimeline()\n    timeline.clear()\n    event = timeline.record(MissionEventType.PLANNER_CREATED_MISSION, "created mission: Test build", confidence=0.95, risk="low")\n    assert event["source"] == "Planner"\n    assert "Test build" in timeline.lines(1)[0]\n    assert "confidence 95%" in timeline.lines(1)[0]\n    bridge = MissionTimelineEventBridge(timeline)\n    bridge.handle({"type": MissionEventType.REPOSITORY_INDEXED, "payload": {"message": "indexed project: demo"}})\n    bridge.handle({"type": MissionEventType.BUILDER_GENERATED_CODE, "payload": {"message": "generated code: main.py", "confidence": 0.88, "risk": "low"}})\n    bridge.handle({"type": MissionEventType.TESTER_FOUND_FAILURE, "payload": {"message": "found 1 failure", "risk": "medium", "level": "warning"}})\n    bridge.handle({"type": MissionEventType.FIXER_REPAIRED_ISSUE, "payload": {"message": "repaired issue", "confidence": 0.82}})\n    bridge.handle({"type": MissionEventType.VERIFIER_APPROVED_BUILD, "payload": {"message": "approved build"}})\n    bridge.handle({"type": MissionEventType.LEARNING_RECORDED_PATTERN, "payload": {"message": "recorded new pattern"}})\n    bridge.handle({"type": MissionEventType.EXPERIENCE_UPDATED_SKILL, "payload": {"message": "updated Python skill (+0.2%)"}})\n    recent = timeline.recent(10)\n    assert len(recent) >= 8\n    assert any(e["source"] == "Tester" for e in recent)\n    assert any("Python skill" in e["message"] for e in recent)\n    view = LiveMissionTimelineView().get_view_model()\n    assert view["title"] == "Live Mission Timeline"\n    assert view["lines"]\n    widget = LiveMissionTimelineWidgetModel().get_view_model()\n    assert "empty_message" in widget\n    assert "events" in widget\n    planner = TimelinePlannerBridge()\n    planner.mission_created("Planner bridge build", 0.91, "low", "test")\n    planner.agent_step("Builder", "generated code", 0.89, "low")\n    assert any("Planner bridge build" in line for line in timeline.lines(10))\n    data = json.loads(Path("data/mission_timeline_live.json").read_text(encoding="utf-8"))\n    assert isinstance(data, list)\n    assert data\n    print("SUCCESS: v4.2 Live Mission Timeline tests passed")\n\nif __name__ == "__main__":\n    main()\n'
JSON_DEFAULTS = {
    "data/live_mission_timeline_state.json": {
        "enabled": True,
        "updated": now_iso(),
        "description": "Live mission timeline state for Mission Control.",
        "connected_sources": ["planner", "repository", "builder", "tester", "fixer", "verifier", "learning", "experience"],
    },
    "data/mission_timeline_live.json": [],
}

def write_file(rel: str, content: str) -> None:
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content.strip() + "\n", encoding="utf-8")
    print(f"[WRITE] {rel}")

def create_json(rel: str, default):
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        path.write_text(json.dumps(default, indent=2), encoding="utf-8")
        print(f"[CREATE] {rel}")
    else:
        print(f"[SKIP] {rel}")

def main():
    print("=== Applying Buster v4.2 Live Mission Timeline Patch ===")
    for rel, content in FILES.items():
        write_file(rel, content)
    for rel, default in JSON_DEFAULTS.items():
        create_json(rel, default)
    print()
    print("SUCCESS: Buster v4.2 Live Mission Timeline installed.")
    print("Next: python test_v4_2_live_mission_timeline.py")

if __name__ == "__main__":
    main()
